<?php use App\Models\Content;use App\Services\Navigation;
$topbarPhone=setting('topbar_phone')?:setting('phone');
$topbarEmail=setting('topbar_email')?:setting('email');
$topbarBrand=setting('topbar_brand_text');
$topbarLocation=setting('topbar_location');
$topbarSocials=[];foreach(['Facebook'=>['facebook_url','show_facebook_icon','fa-facebook-f'],'LinkedIn'=>['linkedin_url','show_linkedin_icon','fa-linkedin-in'],'Instagram'=>['instagram_url','show_instagram_icon','fa-instagram']] as $label=>[$key,$toggle,$icon])if(setting($toggle,'1')==='1'&&$url=setting($key))$topbarSocials[]=['title'=>$label,'custom_url'=>$url,'icon'=>'fa-brands '.$icon];
$topbarWhatsApp=setting('whatsapp_url')?:setting('whatsapp');
?>
<div id="siteHeaderGroup"><div class="topbar-pro"><div class="container"><div class="tb-left"><span class="tb-tagline"><?php if($topbarBrand):?><strong><?=e($topbarBrand)?></strong><?php endif?><?php $topbarText=setting('announcement')?:setting('topbar_text');if($topbarText):?><?=($topbarBrand?' · ':'')?><?=e($topbarText)?><?php endif?></span><?php if(setting('show_topbar_location','1')==='1'&&$topbarLocation):?><span class="tb-location"><i class="fa-solid fa-location-dot" aria-hidden="true"></i><?=e($topbarLocation)?></span><?php endif?></div><div class="tb-right"><?php if($topbarPhone):?><a href="tel:<?=e(preg_replace('/[^+0-9]/','',$topbarPhone))?>"><i class="fa-solid fa-phone"></i> <span><?=e($topbarPhone)?></span></a><?php endif?><?php if($topbarEmail):?><span class="tb-divider"></span><a href="mailto:<?=e($topbarEmail)?>"><i class="fa-regular fa-envelope"></i> <span><?=e($topbarEmail)?></span></a><?php endif?><div class="tb-social"><?php foreach($topbarSocials as $social):?><a href="<?=e(cms_url($social['custom_url']))?>" aria-label="<?=e($social['title'])?>" target="_blank" rel="noopener noreferrer"><i class="<?=e($social['icon'])?>"></i></a><?php endforeach?><?php if(setting('show_whatsapp_icon','1')==='1'&&$topbarWhatsApp):?><a href="<?=e(str_starts_with($topbarWhatsApp,'http')?$topbarWhatsApp:'https://wa.me/'.preg_replace('/\D/','',$topbarWhatsApp))?>" target="_blank" rel="noopener noreferrer" aria-label="WhatsApp"><i class="fa-brands fa-whatsapp"></i></a><?php endif?></div></div></div></div>
<header class="main-header" id="siteHeader"><div class="nav-wrap"><a class="brand" href="<?=e(cms_url(setting('logo_link','/')))?>"><?php if(setting('header_logo')):?><?=media_img(setting('header_logo'),setting('company_name'),'site-header-logo',false)?><?php else:?><h1><?=e(setting('company_name'))?></h1><?php endif?><?php if(setting('alternate_logo')):?><?=media_img(setting('alternate_logo'),setting('company_name'),'cms-alternate-logo',false)?><?php endif?></a><nav class="primary-nav <?=setting('mobile_navigation')==='expanded'?'cms-mobile-expanded':''?>" aria-label="<?=text('main_navigation')?>"><ul><?php foreach(Content::published('navigation_menus',"location='header'") as $menu){$items=Content::published('navigation_items','menu_id=?',[$menu['id']]);Navigation::renderItems($items);}?></ul></nav><div class="nav-actions"><?php if(setting('search_visible')==='1'):?><button class="cms-search-button" id="searchOpen" type="button" aria-label="<?=text('search')?>"><i class="fa-solid fa-magnifying-glass"></i></button><?php endif?><?php if(setting('product_search')==='1'):?><a class="nav-product-search" data-search-template="<?=text('search_template')?>" href="<?=e(cms_url('/products/#product-search'))?>" aria-label="<?=text('product_search')?>"><i class="fa-solid fa-magnifying-glass" aria-hidden="true"></i><span class="nav-search-placeholder"><?=text('product_search')?></span><span class="nav-search-terms" hidden><?php foreach(Content::published('categories','1=1',[],10) as $category):?><span data-nav-search-term><?=e($category['title'])?></span><?php endforeach?></span></a><?php endif?><?php if(setting('cta_label')):?><a href="<?=e(cms_url(setting('cta_url')))?>" class="btn btn-primary"><?=e(setting('cta_label'))?></a><?php endif?><button class="menu-toggle" id="menuToggle" aria-label="<?=text('toggle_menu')?>" aria-expanded="false"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 12h18M3 6h18M3 18h18"/></svg></button></div></div></header></div>
